using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
public enum StreetLegendMissionStage{HotelCombat,DrivingPursuit,Roadblock,PostRoadblockCombat,Complete}
/// <summary>Campaign phase coordinator, with independent roadblock fight and victory handoff.</summary>
public class StreetLegendMissionPhase:MonoBehaviour{
 public StreetLegendVehicleController vehicle;public GameObject drivingHUD,combatHUD,roadblockHUD;public PrototypeMobileHUD mobileHUD;
 public PrototypeFighterController player,roadblockFighter;public PrototypeOpponent roadblockOpponent;
 public Transform safeExitPoint,roadblockOpponentPoint;public StreetLegendMissionStage phase=StreetLegendMissionStage.HotelCombat;
 bool triggered,combatStarted,won;void Update(){if(phase==StreetLegendMissionStage.PostRoadblockCombat&&!won&&roadblockOpponent&&roadblockOpponent.Health<=0){won=true;Finish();}}
 public void BeginPursuit(){if(phase!=StreetLegendMissionStage.HotelCombat)return;phase=StreetLegendMissionStage.DrivingPursuit;if(vehicle){vehicle.gameObject.SetActive(true);vehicle.SetDrivingEnabled(true);}if(drivingHUD)drivingHUD.SetActive(true);if(combatHUD)combatHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);}
 public void RoadblockReached(){if(phase!=StreetLegendMissionStage.DrivingPursuit||triggered)return;triggered=true;phase=StreetLegendMissionStage.Roadblock;if(vehicle){vehicle.StopVehicle();vehicle.SetDrivingEnabled(false);}if(drivingHUD)drivingHUD.SetActive(false);if(player){if(safeExitPoint)player.transform.position=safeExitPoint.position;player.ResetVerticalMotion();player.enabled=true;}if(roadblockFighter){roadblockFighter.gameObject.SetActive(true);if(roadblockOpponentPoint)roadblockFighter.transform.position=roadblockOpponentPoint.position;roadblockFighter.enabled=true;}if(roadblockOpponent){roadblockOpponent.gameObject.SetActive(true);if(player)roadblockOpponent.SetTarget(player.transform);}if(player&&roadblockFighter)player.SetOpponent(roadblockFighter.transform);if(mobileHUD)mobileHUD.RefreshOpponent();BeginRoadblockCombat();}
 public void BeginRoadblockCombat(){if(phase!=StreetLegendMissionStage.Roadblock||combatStarted)return;combatStarted=true;phase=StreetLegendMissionStage.PostRoadblockCombat;if(combatHUD)combatHUD.SetActive(true);if(mobileHUD)mobileHUD.SetHUDVisible(true);if(mobileHUD)mobileHUD.SetHUDVisible(true);if(roadblockHUD)roadblockHUD.SetActive(true);}
 public void Finish(){if(phase!=StreetLegendMissionStage.PostRoadblockCombat)return;phase=StreetLegendMissionStage.Complete;if(roadblockHUD)roadblockHUD.SetActive(false);if(combatHUD)combatHUD.SetActive(false);if(mobileHUD)mobileHUD.SetHUDVisible(false);if(player)player.enabled=false;if(roadblockOpponent)roadblockOpponent.enabled=false;ShowCompletionPanel();Debug.Log("Level 1 roadblock encounter cleared. Campaign handoff is ready.");}

 void ShowCompletionPanel(){var canvasObj=new GameObject("Level Complete Overlay",typeof(Canvas),typeof(CanvasScaler));var canvas=canvasObj.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=80;var scaler=canvasObj.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);var panel=new GameObject("Completion Panel",typeof(RectTransform),typeof(Image));panel.transform.SetParent(canvasObj.transform,false);var rect=panel.GetComponent<RectTransform>();rect.anchorMin=new Vector2(.25f,.25f);rect.anchorMax=new Vector2(.75f,.75f);rect.offsetMin=rect.offsetMax=Vector2.zero;panel.GetComponent<Image>().color=new Color(.035f,.07f,.12f,.94f);var label=new GameObject("Victory Title",typeof(RectTransform),typeof(Text));label.transform.SetParent(panel.transform,false);var lr=label.GetComponent<RectTransform>();lr.anchorMin=new Vector2(.05f,.55f);lr.anchorMax=new Vector2(.95f,.95f);lr.offsetMin=lr.offsetMax=Vector2.zero;var txt=label.GetComponent<Text>();txt.font=Resources.GetBuiltinResource<Font>("Arial.ttf");txt.text="LEVEL 1 COMPLETE\\nROADBLOCK CLEARED";txt.fontSize=48;txt.fontStyle=FontStyle.Bold;txt.alignment=TextAnchor.MiddleCenter;txt.color=Color.white;var buttonObj=new GameObject("Continue Button",typeof(RectTransform),typeof(Image),typeof(Button));buttonObj.transform.SetParent(panel.transform,false);var br=buttonObj.GetComponent<RectTransform>();br.anchorMin=new Vector2(.3f,.12f);br.anchorMax=new Vector2(.7f,.42f);br.offsetMin=br.offsetMax=Vector2.zero;buttonObj.GetComponent<Image>().color=new Color(.12f,.48f,.72f);buttonObj.GetComponent<Button>().onClick.AddListener(()=>SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex));var bt=new GameObject("Button Label",typeof(RectTransform),typeof(Text));bt.transform.SetParent(buttonObj.transform,false);var btr=bt.GetComponent<RectTransform>();btr.anchorMin=Vector2.zero;btr.anchorMax=Vector2.one;btr.offsetMin=btr.offsetMax=Vector2.zero;var btext=bt.GetComponent<Text>();btext.font=Resources.GetBuiltinResource<Font>("Arial.ttf");btext.text="REPLAY LEVEL";btext.fontSize=32;btext.fontStyle=FontStyle.Bold;btext.alignment=TextAnchor.MiddleCenter;btext.color=Color.white;}
 public void ResetMission(){triggered=combatStarted=won=false;phase=StreetLegendMissionStage.HotelCombat;if(vehicle){vehicle.StopVehicle();vehicle.SetDrivingEnabled(false);}if(drivingHUD)drivingHUD.SetActive(false);if(roadblockHUD)roadblockHUD.SetActive(false);if(combatHUD)combatHUD.SetActive(true);}
}